class RPSGame:
    def __init__(self):
        self.player_score = 0
        self.cpu_score = 0

    def play_round(self):
        cpu_choice = random.choice(['rock', 'paper', 'scissors'])
        player_choice = input('Your choice (rock, paper, scissors): ') or 'rock'
        if player_choice not in ['rock', 'paper', 'scissors']:
            return None, 'Invalid choice, please pick rock, paper, or scissors.'

        if player_choice == cpu_choice:
            return cpu_choice, 'Tie'
        elif (player_choice == 'rock' and cpu_choice == 'scissors') or (player_choice == 'paper' and cpu_choice == 'rock') or (player_choice == 'scissors' and cpu_choice == 'paper'):
            self.player_score += 1
            return cpu_choice, 'Player wins'
        else:
            self.cpu_score += 1
            return cpu_choice, 'CPU wins'

    def get_scores(self):
        return self.player_score, self.cpu_score

def play_rps_game():
    game = RPSGame()
    rounds = 5
    for _ in range(rounds):
        cpu_choice, result = game.play_round()
        print(f'Round {game.get_scores()[0]}: CPU chose {cpu_choice}, {result}')
    player_score, cpu_score = game.get_scores()
    print(f'Final score: Player {player_score} - CPU {cpu_score}')
