import sys

class DisplayState:
    def __init__(self, word: str, guesses: list[str]):
        self.word = word
        self.guesses = guesses

    def win(self) -> bool:
        return all(char in self.guesses for char in self.word)

class Game:
    def __init__(self, word: str):
        self.word = word
        self.state = DisplayState(word, [])

    def guess(self, char: str) -> None:
        self.state.guesses.append(char)

def main():
    game = Game('PYTHON')
    for char in 'PYTHON':
        game.guess(char)
        display = game.state.word
        for c in display:
            if c in game.state.guesses:
                sys.stdout.write(f'{c} ')
            else:
                sys.stdout.write('_ ')
        sys.stdout.write('\n')
        if game.state.win:
            print('You won!')
            return

if __name__ == '__main__':
    main()
