import json
import os
from typing import Dict

class Expense:
    def __init__(self, name: str, amount: float):
        self.name = name
        self.amount = amount

def load_expenses(file_path: str) -> Dict[str, float]:
    try:
        with open(file_path, 'r') as f:
            data = json.load(f)
            return {item['name']: item['amount'] for item in data}
    except FileNotFoundError:
        return {}

def save_expenses(file_path: str, expenses: Dict[str, float]):
    data = [{'name': k, 'amount': v} for k, v in expenses.items()]
    with open(file_path, 'w') as f:
        json.dump(data, f, indent=2)

def main() -> None:
    file_path = 'expenses.json'
    if os.path.exists(file_path):
        expenses = load_expenses(file_path)
    else:
        expenses = {}

    expenses['coffee'] = 4.50
    expenses['lunch'] = 12.00

    save_expenses(file_path, expenses)
    total_spent = sum(expenses.values())
    print('Expenses:')
    for name, amount in expenses.items():
        print(f'  {name}: {amount:.2f}')
    print(f'Total spent: {total_spent:.2f}')

if __name__ == '__main__':
