import sys

class TodoList:
    def __init__(self):
        self.items = []

    def add(self, item: str) -> None:
        self.items.append(item)

    def list(self) -> None:
        for idx, item in enumerate(self.items):
            state = '[x]' if item.startswith('[x] ') else '[ ]'
            print(f'{state} {item}')

    def complete(self, index: int) -> None:
