import re

def markdown_to_html(md: str) -> str:
    lines = md.split('\n')
    html = []
    in_list = False
    for line in lines:
        if re.match(r'^\s*#', line):
            level = len(re.match(r'^\s*#{1,}', line).group(0))
            html.append(f'<h{level}>{line[level:].strip()}</h{level}>')
        elif re.match(r'^\s*-', line):
            in_list = True
            html.append('<ul><li>')
        elif in_list:
            in_list = False
            html.append('</li></ul><ul><li>')
            html.append(line[4:].strip())
        elif re.match(r'^\s*\*\s', line):
            in_list = True
            html.append('<ul><li>')
            html.append(line[4:].strip())
        elif re.match(r'^\s*[\*\-\+]\s', line):
            in_list = True
            html.append('<ul><li>')
            html.append(line[4:].strip())
        elif re.match(r'^\s*\[.*?\]\(.*?\)', line):
            text, url = re.match(r'\[(.*?)\]\((.*?)\)', line).groups()
            html.append(f'<a href="{url}">{text}</a>')
        elif re.match(r'^\s*!\[.*?\]\(.*?\)', line):
            text, url = re.match(r'!\[(.*?)\]\((.*?)\)', line).groups()
            html.append(f'<img src="{url}" alt="{text}">')
        elif re.match(r'^\s*__.*?__', line):
            html.append(f'<strong>{line[2:-2].strip()}</strong>')
        else:
            html.append(line)
    if in_list:
        html.append('</li></ul>')
    return '\n'.join(html)

if __name__ == '__main__':
    sample_md = '# Heading\n\n__Bold phrase__\n\n- List item 1\n- List item 2\n- [Link](http://example.com)\n\n![Alt text](https://path/to/image.png)'
    print(markdown_to_html(sample_md))
