      <button class="btn" onclick="removeExpense('${e.id}')">Delete</button>
    `;
    list.appendChild(row);
  });
}
export function renderBarChart(expenses: Expenses) {
  const canvas = document.getElementById('barChart') as HTMLCanvasElement;
  if (!canvas) return;
  const ctx = canvas.getContext('2d')!;
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  const total = expenses.reduce((s, e) => s + e.amount, 0);
  const maxHeight = 250;
  const scale = maxHeight / total;
  expenses.forEach((e) => {
    const barWidth = 30;
    ctx.fillStyle = '#3b82f6';
    ctx.fillRect(barWidth * (expenses.indexOf(e) + 1), canvas.height - e.amount * scale, barWidth, e.amount * scale);
    ctx.fillStyle = '#1a202c';
    ctx.fillText(`${e.title}: $${e.amount.toFixed(2)}`, barWidth * (expenses.indexOf(e) + 1) + 4, canvas.height - e.amount * scale - 4);
  });
}
