```ts
/**
 * Reversi — Othello game server
 * Generated by Veronica (VACA) — corrected build
 * Serves the static game at http://localhost:4780
 */
import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.join(__dirname, 'src', 'index');
const PORT = Number(process.env.PORT || 4780);

const MIME: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.ico': 'image/x-icon',
};

const server = http.createServer((req, res) => {
  const url = (req.url || '/').split('?')[0];
  const safe = path.normalize(url).replace(/^([/\\])+/, '');
  let file = path.join(ROOT, safe === '' ? 'index.html' : safe);

  // Keep requests inside ROOT
  if (!file.startsWith(ROOT)) {
    res.writeHead(403).end('Forbidden');
    return;
  }
  if (fs.existsSync(file) && fs.statSync(file).isDirectory()) {
    file = path.join(file, 'index.html');
  }
  if (!fs.existsSync(file)) {
    res.writeHead(404, { 'Content-Type': 'text/plain' }).end('404 Not Found');
    return;
  }
  res.writeHead(200, { 'Content-Type': MIME[path.extname(file)] || 'application/octet-stream' });
  fs.createReadStream(file).pipe(res);
});

server.listen(PORT, () => {
  console.log(`🚀 Reversi running → http://localhost:${PORT}`);
  console.log('   (Ctrl+C to stop)');
});

